diff --git a/src/http/client.ts b/src/http/client.ts
new file mode 100644
index 0000000..590ff30
--- /dev/null
+++ b/src/http/client.ts
@@ -0,0 +1,86 @@
+import { userAgent } from "../util/version";
+import { HttpError, TimeoutError } from "./errors";
+
+const DEFAULT_TIMEOUT_MS = 30_000;
+
+export interface HttpClientOptions {
+  baseUrl: string;
+  token?: string;
+  timeoutMs?: number;
+  headers?: Record<string, string>;
+}
+
+type Method = "GET" | "POST" | "PUT" | "DELETE";
+
+export class HttpClient {
+  private readonly baseUrl: string;
+  private readonly token?: string;
+  private readonly timeoutMs: number;
+  private readonly extraHeaders: Record<string, string>;
+
+  constructor(options: HttpClientOptions) {
+    this.baseUrl = options.baseUrl.replace(/\/+$/, "");
+    this.token = options.token;
+    this.timeoutMs = options.timeoutMs ?? DEFAULT_TIMEOUT_MS;
+    this.extraHeaders = options.headers ?? {};
+  }
+
+  get(path: string): Promise<unknown> {
+    return this.send("GET", path);
+  }
+
+  post(path: string, body?: unknown): Promise<unknown> {
+    return this.send("POST", path, body);
+  }
+
+  put(path: string, body?: unknown): Promise<unknown> {
+    return this.send("PUT", path, body);
+  }
+
+  delete(path: string, body?: unknown): Promise<unknown> {
+    return this.send("DELETE", path, body);
+  }
+
+  private headers(hasBody: boolean): Record<string, string> {
+    return {
+      accept: "application/json",
+      "user-agent": userAgent(),
+      ...(hasBody ? { "content-type": "application/json" } : {}),
+      ...(this.token ? { authorization: `Bearer ${this.token}` } : {}),
+      ...this.extraHeaders,
+    };
+  }
+
+  private async send(method: Method, path: string, body?: unknown): Promise<unknown> {
+    const controller = new AbortController();
+    const timer = setTimeout(() => controller.abort(), this.timeoutMs);
+    let response: Response;
+    try {
+      response = await fetch(`${this.baseUrl}${path}`, {
+        method,
+        signal: controller.signal,
+        headers: this.headers(body !== undefined),
+        body: body === undefined ? undefined : JSON.stringify(body),
+      });
+    } catch (error) {
+      if ((error as Error).name === "AbortError") {
+        throw new TimeoutError(method, path, this.timeoutMs);
+      }
+      throw error;
+    } finally {
+      clearTimeout(timer);
+    }
+    if (!response.ok) {
+      const text = await response.text();
+      throw new HttpError(response.status, response.statusText, text.slice(0, 200));
+    }
+    if (response.status === 204) {
+      return undefined;
+    }
+    const contentType = response.headers.get("content-type") ?? "";
+    if (!contentType.includes("application/json")) {
+      throw new HttpError(response.status, "Unexpected content type", contentType);
+    }
+    return response.json();
+  }
+}
